class BasesVisualsHost {
  constructor(controller, moduleInstance) {
    this.controller = controller;
    this.module = moduleInstance;
    this.tabStripEl = null;
    this.paginationBarEl = null;
    this.toolsToggleBtn = null;
    this.visualsBtn = null;
    this.draggingTabName = null;

    this.cleanups = [];

    // Hook Bases DataClass (cG) prototype to execute immediate pagination
    this.hookBasesDataClass();

    // Hook view-changed event from Bases controller
    if (controller.events?.on) {
      const ref = controller.events.on("view-changed", () => {
        const config = this.getViewConfig();
        if (config) config.__currentPage = 1;
        this.hookView();
        this.renderTabs();
        this.syncToolbarTools();
        this.updatePaginationBar();
        this.triggerCommunityBasesVisualsEnhancer();
        this.processSelectCells();
      });
      this.cleanups.push(() => controller.events.offref?.(ref));
    }

    // Hook notifyView to catch view updates and pagination calculations
    this.hookNotifyView();
    this.hookView();

    // Initial mount
    this.renderTabs();
    this.syncToolbarTools();
    this.updatePaginationBar();
    this.triggerCommunityBasesVisualsEnhancer();
  }

  // Trigger Community "Bases Visuals" (bases-pill-colors) enhancer on this view
  
  // Cancel button support for all list items, multi-select pills, and single-select cells
  processPillsAndListCells() {
    const container = this.controller.viewContainerEl;
    if (!container) return;

    // 1. Process all pills in lists (multi-select, tags, bpc pills, metadata pills)
    const pills = container.querySelectorAll(
      ".multi-select-pill, .bpc-pill, .metadata-property-pill, .bases-cell-list-item"
    );

    for (const pill of Array.from(pills)) {
      if (pill.querySelector(".multi-select-pill-remove-button, .bases-pill-cancel-btn")) {
        continue;
      }

      const cancelBtn = document.createElement("button");
      cancelBtn.type = "button";
      cancelBtn.className = "multi-select-pill-remove-button bases-pill-cancel-btn clickable-icon";
      cancelBtn.setAttribute("aria-label", "Remove from list");
      cancelBtn.title = "Remove from list";
      if (setIcon) setIcon(cancelBtn, "lucide-x"); else cancelBtn.setText("×");

      cancelBtn.addEventListener("click", async (e) => {
        e.preventDefault();
        e.stopPropagation();
        await this.removeListItem(pill);
      });

      pill.appendChild(cancelBtn);
    }

    // 2. Process single-select cells
    const cells = container.querySelectorAll(".bpc-select-cell");
    for (const cell of Array.from(cells)) {
      if (!cell.querySelector(".bpc-select-clear-btn") && (cell.dataset.bpcKey || cell.textContent?.trim())) {
        const clearBtn = document.createElement("button");
        clearBtn.type = "button";
        clearBtn.className = "bpc-select-clear-btn clickable-icon";
        clearBtn.setAttribute("aria-label", "Clear value");
        clearBtn.title = "Clear value";
        if (setIcon) setIcon(clearBtn, "lucide-x"); else clearBtn.setText("×");
        clearBtn.addEventListener("click", async (e) => {
          e.preventDefault();
          e.stopPropagation();
          await this.clearSingleSelectCell(cell);
        });
        cell.appendChild(clearBtn);
      }
    }
  }

  processSelectCells() {
    this.processPillsAndListCells();
  }

  async removeListItem(pill) {
    const app = this.module.ctx.app;
    if (!app) return;

    const nativeBtn = pill.querySelector(".multi-select-pill-remove-button:not(.bases-pill-cancel-btn)");
    if (nativeBtn) {
      nativeBtn.click();
      return;
    }

    const cell = pill.closest(".bases-td, .bases-cell, [data-property], .bpc-pill-container, .metadata-property") || pill.parentElement;
    const row = pill.closest(".bases-tr, .bases-cards-item, .bases-list-item, tr") || cell?.parentElement;
    if (!cell || !row) return;

    const linkEl = row.querySelector("a.internal-link[data-href], .internal-link, a[data-href], a[href]");
    const href = linkEl?.dataset?.href || linkEl?.getAttribute("data-href") || linkEl?.getAttribute("href") || linkEl?.textContent?.trim();

    const propId = cell.dataset?.property?.trim() ||
                   cell.dataset?.bpcKey?.trim() ||
                   cell.getAttribute?.("data-property-key") ||
                   cell.closest?.("[data-property]")?.dataset?.property;

    const pillText = pill.querySelector(".multi-select-pill-content, .bpc-pill__label, span")?.textContent?.trim() ||
                     pill.textContent?.replace(/[×x]/g, "").trim();

    if (href && propId && pillText && app.metadataCache && app.fileManager) {
      const cleanHref = href.replace(/^#/, "").split("#")[0];
      const file = app.metadataCache.getFirstLinkpathDest(cleanHref, "");
      if (file) {
        await app.fileManager.processFrontMatter(file, (fm) => {
          const currentVal = fm[propId];
          if (Array.isArray(currentVal)) {
            fm[propId] = currentVal.filter(item => {
              const str = typeof item === "string" ? item.trim() : JSON.stringify(item);
              return str !== pillText && !str.includes(pillText);
            });
            if (fm[propId].length === 0) {
              delete fm[propId];
            }
          } else if (typeof currentVal === "string" && (currentVal.trim() === pillText || currentVal.includes(pillText))) {
            delete fm[propId];
          }
        });

        pill.style.transition = "opacity 150ms ease, transform 150ms ease";
        pill.style.opacity = "0";
        pill.style.transform = "scale(0.8)";
        setTimeout(() => {
          pill.remove();
          if (typeof this.controller.notifyView === "function") {
            this.controller.notifyView();
          }
        }, 150);
        return;
      }
    }

    pill.remove();
  }

  async clearSingleSelectCell(cell) {
    const app = this.module.ctx.app;
    const row = cell.closest(".bases-tr, .bases-cards-item, .bases-list-item, tr") || cell.parentElement;
    if (!row || !app) return;

    const nativeBtn = cell.querySelector(".multi-select-pill-remove-button");
    if (nativeBtn) {
      nativeBtn.click();
      return;
    }

    const linkEl = row.querySelector("a.internal-link[data-href], .internal-link, a[data-href], a[href]");
    const href = linkEl?.dataset?.href || linkEl?.getAttribute("data-href") || linkEl?.getAttribute("href") || linkEl?.textContent?.trim();
    const propId = cell.dataset?.property?.trim() || cell.dataset?.bpcKey?.trim();

    if (href && propId && app.metadataCache && app.fileManager) {
      const cleanHref = href.replace(/^#/, "").split("#")[0];
      const file = app.metadataCache.getFirstLinkpathDest(cleanHref, "");
      if (file) {
        await app.fileManager.processFrontMatter(file, (fm) => {
          delete fm[propId];
        });
        if (typeof this.controller.notifyView === "function") {
          setTimeout(() => this.controller.notifyView(), 50);
        }
        return;
      }
    }

    const textEl = cell.querySelector(".metadata-input-longtext, .metadata-input-text");
    if (textEl) {
      textEl.textContent = "";
      textEl.dispatchEvent(new Event("input", { bubbles: true }));
      textEl.dispatchEvent(new Event("change", { bubbles: true }));
    }
  }

  // Open Iconic icon picker from Iconic plugin library or builtin fuzzy search
  openIconicPickerForView(viewDef, callback) {
    const app = this.controller.plugin?.app || this.module.ctx.app;
    const iconic = app?.plugins?.plugins?.["iconic"];
    const viewMeta = viewDef?.get?.(STORAGE_KEY) || {};
    const currentIcon = viewMeta.tabIcon || this.getDefaultViewIcon(viewDef?.type);
    const currentColor = viewMeta.tabColor || null;
    const viewName = viewDef?.name || this.controller.viewName;

    const item = {
      id: viewName,
      name: viewName,
      category: "tab",
      icon: currentIcon,
      color: currentColor
    };

    // 1. Direct openIconPicker if exposed
    if (typeof iconic?.openIconPicker === "function") {
      iconic.openIconPicker(item, callback);
      return;
    }

    // 2. Global IconicPicker modal
    if (window.IconicPicker?.openSingle) {
      window.IconicPicker.openSingle(iconic, item, callback);
      return;
    }

    // 3. Fallback: Fuzzy search modal with all Obsidian icons
    this.openBuiltinIconPicker(item, callback);
  }

  openBuiltinIconPicker(item, callback) {
    const obsApi = getObsidianApi();
    const app = this.controller.plugin?.app || this.module.ctx.app;
    if (!obsApi.FuzzySuggestModal || !app) return;

    class IconSuggestModal extends obsApi.FuzzySuggestModal {
      constructor(app, onChoose) {
        super(app);
        this.onChoose = onChoose;
        this.setPlaceholder("Search icon from library (e.g. table, list, check, star, heart)...");
      }
      getItems() {
        if (typeof obsApi.getIconIds === "function") {
          return obsApi.getIconIds();
        }
        return COMMON_TAB_ICONS.map(i => i.id).filter(Boolean);
      }
      getItemText(item) {
        return item;
      }
      renderSuggestion(match, el) {
        el.addClass("bases-visuals-icon-suggest-item");
        const iconSpan = el.createSpan({ cls: "bases-visuals-suggest-icon" });
        if (obsApi.setIcon) {
          try { obsApi.setIcon(iconSpan, match.item); } catch (_) {}
        }
        el.createSpan({ text: match.item });
      }
      onChooseItem(item) {
        this.onChoose(item, null);
      }
    }

    new IconSuggestModal(app, callback).open();
  }

  triggerCommunityBasesVisualsEnhancer() {
    try {
      const bpc = this.module.ctx.app?.plugins?.plugins?.["bases-pill-colors"] || this.module.bpcPlugin;
      const container = this.controller.viewContainerEl;
      if (bpc?.enhancer) {
        if (container) {
          bpc.enhancer.refreshAround?.(container);
          bpc.enhancer.processTree?.(container);
        }
        const toolbar = this.controller.viewHeaderEl?.querySelector(".bases-toolbar");
        if (toolbar) {
          bpc.enhancer.processToolbar?.(toolbar);
        }
      }
    } catch (_) {}
  }

  // Get current view's configuration object from query
  getViewConfig() {
    try {
      return this.controller.query?.getViewConfig?.(this.controller.viewName);
    } catch (_) {
      return null;
    }
  }

  // Read stored visual settings
  getSettings(targetConfig = null) {
    const config = targetConfig || this.getViewConfig();
    const raw = config?.get?.(STORAGE_KEY) || {};
    return {
      showTabs: raw.showTabs !== false,
      tabColor: TAB_COLORS.includes(raw.tabColor) ? raw.tabColor : null,
      tabSize: TAB_SIZES.includes(raw.tabSize) ? raw.tabSize : "medium",
      tabIcon: typeof raw.tabIcon === "string" ? raw.tabIcon : null,
      paginationEnabled: raw.paginationEnabled !== false,
      pageSize: typeof raw.pageSize === "number" && raw.pageSize > 0 ? raw.pageSize : (this.module.moduleSettings.defaultPageSize || DEFAULT_PAGE_SIZE),
      autoHidePagination: raw.autoHidePagination === true
    };
  }

  // Save updated settings back to the view definition
  saveSettings(newSettings, targetConfig = null) {
    const config = targetConfig || this.getViewConfig();
    if (!config || typeof config.set !== "function") return;
    const current = this.getSettings(config);
    const merged = { ...current, ...newSettings };
    
    // Reset to page 1 whenever page size or pagination toggle changes
    if (newSettings.pageSize !== undefined || newSettings.paginationEnabled !== undefined) {
      config.__currentPage = 1;
    }

    config.set(STORAGE_KEY, merged);
    this.needsRender = true;
    this.renderTabs();
    if (typeof this.controller.notifyView === "function") {
      this.controller.notifyView();
    }
    // Perform immediate and scheduled updates so pagination row is never lost
    this.updatePaginationBar();
    setTimeout(() => this.updatePaginationBar(), 40);
    setTimeout(() => this.updatePaginationBar(), 120);
    setTimeout(() => this.updatePaginationBar(), 300);
    setTimeout(() => this.updatePaginationBar(), 600);
    this.processPillsAndListCells();
  }

  // -----------------------------------------------------------------------
    // Pillar 1: View Tabs (Native Obsidian Button Styling)
  // -----------------------------------------------------------------------
  renderTabs() {
    const toolbar = this.controller.viewHeaderEl?.querySelector(".bases-toolbar");
    if (!toolbar) return;

    if (!this.tabStripEl) {
      this.tabStripEl = createDiv({ cls: "bases-visuals-tab-strip" });
      
      // Horizontal mouse-wheel & trackpad scroll support
      this.tabStripEl.addEventListener("wheel", (evt) => {
        if (this.tabStripEl.scrollWidth <= this.tabStripEl.clientWidth) return;
        const delta = Math.abs(evt.deltaX) >= Math.abs(evt.deltaY) ? evt.deltaX : evt.deltaY;
        if (delta !== 0) {
          evt.preventDefault();
          this.tabStripEl.scrollLeft += delta;
        }
      }, { passive: false });

      this.tabStripEl.addEventListener("scroll", () => this.updateOverflow());
      
      const resizeObserver = new ResizeObserver(() => this.updateOverflow());
      resizeObserver.observe(this.tabStripEl);
      this.cleanups.push(() => resizeObserver.disconnect());
    }

    const leftToggleBtn = toolbar.querySelector(".bases-left-defaults-toggle-btn");
    const resultCountEl = toolbar.querySelector(".bases-toolbar-result-count");
    const viewsMenuEl = toolbar.querySelector(".bases-toolbar-views-menu");
    const leftAnchor = leftToggleBtn || resultCountEl || viewsMenuEl;

    if (leftAnchor && leftAnchor.parentElement === toolbar) {
      if (this.tabStripEl.previousElementSibling !== leftAnchor) {
        leftAnchor.after(this.tabStripEl);
      }
    } else {
      toolbar.prepend(this.tabStripEl);
    }
    toolbar.addClass("has-bases-visuals-tabs");

    this.tabStripEl.empty();

    const viewNames = this.controller.getQueryViewNames?.() || [];
    const activeViewName = this.controller.viewName;
    const viewsList = this.controller.query?.views || [];

    let activeTabBtn = null;

    for (const name of viewNames) {
      const viewDef = viewsList.find(v => v.name === name);
      const viewMeta = viewDef?.get?.(STORAGE_KEY) || {};
      const isVisible = viewMeta.showTabs !== false;
      if (!isVisible) continue;

      const size = TAB_SIZES.includes(viewMeta.tabSize) ? viewMeta.tabSize : "medium";
      const color = TAB_COLORS.includes(viewMeta.tabColor) ? viewMeta.tabColor : null;

      // Obsidian default button styling: 'bases-visuals-tab button'
      const btn = this.tabStripEl.createEl("button", {
        cls: `bases-visuals-tab button mod-${size}`,
        attr: { type: "button", title: name }
      });

      // Icon container at start of tab title (explicit tabIcon > view dropdown registration > viewDef icon > default fallback)
      const iconName = viewMeta.tabIcon ||
        this.controller.plugin?.getRegistration?.(viewDef?.type)?.icon ||
        this.controller.plugin?.viewTypes?.get?.(viewDef?.type)?.icon ||
        viewDef?.icon ||
        this.getDefaultViewIcon(viewDef?.type);

      if (iconName) {
        const iconEl = btn.createSpan({ cls: "bases-visuals-tab-icon" });
        if (setIcon) {
          try {
            setIcon(iconEl, iconName);
          } catch (_) {}
        }
      }

      // Tab title text
      btn.createSpan({ cls: "bases-visuals-tab-title", text: name });

      if (color) btn.dataset.color = color;
      if (name === activeViewName) {
        btn.addClass("is-active");
        activeTabBtn = btn;
      }

      btn.addEventListener("click", () => {
        try {
          this.controller.selectView?.(name);
        } catch (_) {}
      });

      // Context menu: directly open Configure view attached to this tab button
      btn.addEventListener("contextmenu", (evt) => {
        evt.preventDefault();
        evt.stopPropagation();
        if (this.controller.viewName !== name) {
          try { this.controller.selectView(name); } catch (_) {}
          setTimeout(() => {
            this.openConfigureView(btn);
          }, 60);
        } else {
          this.openConfigureView(btn);
        }
      });

      // Drag to reorder
      if (viewsList.length > 1) {
        this.makeDraggable(btn, name, viewsList);
      }
    }

    if (activeTabBtn) {
      this.revealTab(activeTabBtn);
    }
    this.updateOverflow();
  }

  getDefaultViewIcon(viewType) {
    if (!viewType) return "table";
    const t = String(viewType).toLowerCase();
    if (t.includes("table")) return "table";
    if (t.includes("card") || t.includes("gallery")) return "layout-grid";
    if (t.includes("list")) return "list";
    if (t.includes("kanban") || t.includes("board")) return "columns-3";
    if (t.includes("cal")) return "calendar";
    if (t.includes("time") || t.includes("clock")) return "clock";
    if (t.includes("map")) return "map-pin";
    if (t.includes("task") || t.includes("todo")) return "check-square";
    return "table";
  }

  revealTab(tabEl) {
    if (!this.tabStripEl || !tabEl) return;
    const strip = this.tabStripEl;
    const start = tabEl.offsetLeft;
    const end = start + tabEl.offsetWidth;
    if (start < strip.scrollLeft) {
      strip.scrollLeft = start;
    } else if (end > strip.scrollLeft + strip.clientWidth) {
      strip.scrollLeft = end - strip.clientWidth;
    }
  }

  updateOverflow() {
    if (!this.tabStripEl) return;
    const el = this.tabStripEl;
    el.toggleClass("has-overflow-start", el.scrollLeft > 0);
    el.toggleClass("has-overflow-end", el.scrollLeft + el.clientWidth < el.scrollWidth - 1);
  }

  makeDraggable(btn, viewName, viewsList) {
    btn.draggable = true;
    btn.addEventListener("dragstart", (e) => {
      this.draggingTabName = viewName;
      e.dataTransfer?.setData("text/plain", viewName);
      if (e.dataTransfer) e.dataTransfer.effectAllowed = "move";
      btn.addClass("is-dragging");
    });

    btn.addEventListener("dragend", () => {
      this.draggingTabName = null;
      btn.removeClass("is-dragging");
      this.tabStripEl?.querySelectorAll(".is-drop-target").forEach(el => el.removeClass("is-drop-target"));
    });

    btn.addEventListener("dragover", (e) => {
      if (!this.draggingTabName || this.draggingTabName === viewName) return;
      e.preventDefault();
      if (e.dataTransfer) e.dataTransfer.dropEffect = "move";
      btn.addClass("is-drop-target");
    });

    btn.addEventListener("dragleave", () => {
      btn.removeClass("is-drop-target");
    });

    btn.addEventListener("drop", (e) => {
      e.preventDefault();
      btn.removeClass("is-drop-target");
      const fromIdx = viewsList.findIndex(v => v.name === this.draggingTabName);
      const toIdx = viewsList.findIndex(v => v.name === viewName);
      this.draggingTabName = null;

      if (fromIdx >= 0 && toIdx >= 0 && fromIdx !== toIdx) {
        const item = viewsList.splice(fromIdx, 1)[0];
        viewsList.splice(toIdx, 0, item);
        try {
          this.controller.query?.save?.();
          this.renderTabs();
        } catch (_) {}
      }
    });
  }

  openTabMenu(evt, viewDef, viewMeta) {
    if (!Menu) return;
    const menu = new Menu();

    menu.addItem(i => {
      i.setTitle("Configure view")
       .setIcon("sliders-horizontal")
       .setSection("manage")
       .onClick(() => {
         if (this.controller.viewName !== viewDef.name) {
           try { this.controller.selectView(viewDef.name); } catch (_) {}
           setTimeout(() => {
             const tabEl = this.tabStripEl?.querySelector(`[data-tab-name="${CSS.escape(viewDef.name)}"]`);
             this.openConfigureView(tabEl);
           }, 80);
         } else {
           const tabEl = this.tabStripEl?.querySelector(`[data-tab-name="${CSS.escape(viewDef.name)}"]`);
           this.openConfigureView(tabEl);
         }
       });
    });

    menu.addItem(i => i.setTitle("Tab Color").setIsLabel(true).setSection("color"));
    menu.addItem(i => i.setTitle("Default").setSection("color").setChecked(!viewMeta.tabColor).onClick(() => {
      this.saveViewMeta(viewDef, { tabColor: null });
    }));

    for (const c of TAB_COLORS) {
      menu.addItem(i => i.setTitle(c.charAt(0).toUpperCase() + c.slice(1)).setSection("color").setChecked(viewMeta.tabColor === c).onClick(() => {
        this.saveViewMeta(viewDef, { tabColor: c });
      }));
    }

    menu.addItem(i => i.setTitle("Tab Size").setIsLabel(true).setSection("size"));
    for (const s of TAB_SIZES) {
      menu.addItem(i => i.setTitle(s.charAt(0).toUpperCase() + s.slice(1)).setSection("size").setChecked(viewMeta.tabSize === s).onClick(() => {
        this.saveViewMeta(viewDef, { tabSize: s });
      }));
    }

    menu.addItem(i => {
      i.setTitle("Change Icon (Iconic)...")
       .setIcon("lucide-image-plus")
       .setSection("icon")
       .onClick(() => {
         this.openIconicPickerForView(viewDef, (newIcon, newColor) => {
           const patch = { tabIcon: newIcon || null };
           if (newColor) patch.tabColor = newColor;
           this.saveViewMeta(viewDef, patch);
         });
       });
    });

    if (viewMeta.tabIcon) {
      menu.addItem(i => {
        i.setTitle("Reset Icon to Default")
         .setIcon("lucide-rotate-ccw")
         .setSection("icon")
         .onClick(() => {
           this.saveViewMeta(viewDef, { tabIcon: null });
         });
      });
    }

    menu.addItem(i => i.setTitle("Hide from tabs").setIcon("lucide-eye-off").setSection("danger").setWarning(true).onClick(() => {
      this.saveViewMeta(viewDef, { showTabs: false });
    }));

    menu.showAtMouseEvent(evt);
  }

  saveViewMeta(viewDef, patch) {
    if (!viewDef || typeof viewDef.set !== "function") return;
    const current = viewDef.get(STORAGE_KEY) || {};
    viewDef.set(STORAGE_KEY, { ...current, ...patch });
    try {
      this.controller.query?.save?.();
      this.renderTabs();
    } catch (_) {}
  }

  // -----------------------------------------------------------------------
  // Pillar 2: Right-Tools Collapse/Expand Toggle & Community Visuals Button
  // -----------------------------------------------------------------------
  syncToolbarTools() {
    const toolbar = this.controller.viewHeaderEl?.querySelector(".bases-toolbar");
    if (!toolbar) return;

    // Ensure Format and Layout buttons exist via BPC enhancer
    const enhancer = this.module.bpcPlugin?.enhancer || this.module.ctx.app?.plugins?.plugins?.["bases-pill-colors"]?.enhancer;
    if (enhancer && typeof enhancer.processToolbar === "function") {
      try { enhancer.processToolbar(toolbar); } catch (_) {}
    }

    // Remove any legacy duplicate visuals manager button
    const legacyVisualsBtn = toolbar.querySelector(".bases-visuals-manager-btn");
    if (legacyVisualsBtn) {
      legacyVisualsBtn.remove();
    }

    // 1. Left Defaults Minimize Toggle Button (Placed after result count button)
    let leftToggleBtn = toolbar.querySelector(".bases-left-defaults-toggle-btn");
    const isLeftMinimized = !!this.module.moduleSettings.leftDefaultsMinimized;

    if (!leftToggleBtn) {
      leftToggleBtn = document.createElement("button");
      leftToggleBtn.type = "button";
      leftToggleBtn.className = "bases-left-defaults-toggle-btn bases-toolbar-item button clickable-icon";

      leftToggleBtn.addEventListener("click", (e) => {
        e.preventDefault();
        e.stopPropagation();
        const next = !this.module.moduleSettings.leftDefaultsMinimized;
        this.module.moduleSettings.leftDefaultsMinimized = next;
        this.module.saveSettings();
        this.module.syncAllLeftDefaultsVisibility();
      });
    }
    this.leftToggleBtn = leftToggleBtn;

    const afterResultEl = toolbar.querySelector(".bases-toolbar-result-count") || toolbar.querySelector(".bases-toolbar-views-menu");
    if (afterResultEl && afterResultEl.parentElement === toolbar) {
      if (leftToggleBtn.previousElementSibling !== afterResultEl) {
        afterResultEl.after(leftToggleBtn);
      }
    } else if (!leftToggleBtn.parentElement) {
      toolbar.prepend(leftToggleBtn);
    }

    if (setIcon) {
      setIcon(leftToggleBtn, isLeftMinimized ? "chevrons-right" : "chevrons-left");
    } else {
      leftToggleBtn.setText(isLeftMinimized ? "»" : "«");
    }
    leftToggleBtn.setAttribute(
      "aria-label",
      isLeftMinimized ? "Expand default view header" : "Minimize default view header"
    );
    leftToggleBtn.title = isLeftMinimized ? "Expand default view header" : "Minimize default view header";

    this.applyLeftDefaultsHiddenState(toolbar, isLeftMinimized);

    // 2. Three Dots "Configure View" Button (Placed beside left to "New", always visible)
    let threeDotsBtn = toolbar.querySelector(".bases-view-config-btn");
    if (!threeDotsBtn) {
      threeDotsBtn = document.createElement("button");
      threeDotsBtn.type = "button";
      threeDotsBtn.className = "bases-view-config-btn bases-toolbar-item button clickable-icon";
      threeDotsBtn.setAttribute("aria-label", "Configure view");
      threeDotsBtn.title = "Configure view";

      if (setIcon) {
        setIcon(threeDotsBtn, "more-horizontal");
      } else {
        threeDotsBtn.setText("⋯");
      }

      threeDotsBtn.addEventListener("click", (e) => {
        e.preventDefault();
        e.stopPropagation();
        this.openConfigureView(threeDotsBtn);
      });
    }

    const newBtn = toolbar.querySelector(".bases-toolbar-new-item-menu") ||
      toolbar.querySelector("[class*='new-item']") ||
      [...toolbar.querySelectorAll(".bases-toolbar-item")].find(b => (b.textContent || "").trim().includes("New"));

    if (newBtn && newBtn.parentElement) {
      if (threeDotsBtn.nextElementSibling !== newBtn) {
        newBtn.parentElement.insertBefore(threeDotsBtn, newBtn);
      }
    } else if (!threeDotsBtn.parentElement) {
      toolbar.appendChild(threeDotsBtn);
    }

    // 3. Injected Tools Collapse Toggle Button (Positioned to the left of Format and all right-side tools)
    let toggleBtn = toolbar.querySelector(".bases-tools-toggle-btn");
    const isMinimized = !!this.module.moduleSettings.toolsMinimized;

    if (!toggleBtn) {
      toggleBtn = document.createElement("button");
      toggleBtn.type = "button";
      toggleBtn.className = "bases-tools-toggle-btn bases-toolbar-item button clickable-icon";
      this.toolsToggleBtn = toggleBtn;

      toggleBtn.addEventListener("click", (e) => {
        e.preventDefault();
        e.stopPropagation();
        const next = !this.module.moduleSettings.toolsMinimized;
        this.module.moduleSettings.toolsMinimized = next;
        this.module.saveSettings();
        this.module.syncAllToolsVisibility();
      });
    }

    // Locate the first right-side tool: Format, Layout, Sort, Filter, Group, Properties, Search
    const toolSelectors = [
      ".bpc-conditional-formatting-button",
      ".bpc-table-layout-button",
      ".bpc-toolbar-control",
      ".bases-toolbar-sort-menu",
      ".bases-toolbar-filter-menu",
      ".bases-toolbar-group-menu",
      ".bases-toolbar-properties-menu",
      ".bases-toolbar-search-menu",
      "[aria-label*='format' i]",
      "[aria-label*='layout' i]",
      "[aria-label*='sort' i]",
      "[aria-label*='filter' i]"
    ];
    const firstTool = toolbar.querySelector(toolSelectors.join(", "));

    if (firstTool && firstTool.parentElement) {
      if (toggleBtn.nextElementSibling !== firstTool) {
        firstTool.parentElement.insertBefore(toggleBtn, firstTool);
      }
    } else {
      const allNewBtns = toolbar.querySelectorAll('.bases-toolbar-new-item-menu, [class*="new-item"]');
      const firstNewBtn = allNewBtns[0];
      if (firstNewBtn && firstNewBtn.parentElement) {
        firstNewBtn.parentElement.insertBefore(toggleBtn, firstNewBtn);
      } else if (!toggleBtn.parentElement) {
        toolbar.appendChild(toggleBtn);
      }
    }

    if (setIcon) {
      setIcon(toggleBtn, isMinimized ? "chevrons-left" : "chevrons-right");
    } else {
      toggleBtn.setText(isMinimized ? "«" : "»");
    }
    toggleBtn.setAttribute("aria-label", isMinimized ? "Expand right tools" : "Minimize right tools");

    this.applyToolsHiddenState(toolbar, isMinimized);
  }

  openConfigureView(anchorEl = null) {
    const viewsMenu = this.controller.viewHeaderEl?.querySelector(".bases-toolbar-views-menu");
    const viewsBtn = viewsMenu?.querySelector(
      ".text-icon-button, button, [role='button'], .clickable-icon"
    );
    if (!viewsBtn) return false;

    // Dynamically retrieve the underlying view menu controller from Bases
    const vm = this.controller.viewMenu ||
      Object.values(this.controller).find(v => v && typeof v === "object" && v.toolbarItem?.menu);
    const origParentEl = vm?.toolbarItem?.menu?.parentEl;

    if (vm?.toolbarItem?.menu && anchorEl) {
      vm.toolbarItem.menu.parentEl = anchorEl;
    }

    const wasHidden = viewsMenu.classList.contains("bases-left-default-hidden");
    if (wasHidden) {
      viewsMenu.classList.remove("bases-left-default-hidden");
    }

    const evt = new MouseEvent("contextmenu", {
      bubbles: true,
      cancelable: true,
      view: window
    });
    viewsBtn.dispatchEvent(evt);

    // Reposition menu directly anchored to anchorEl
    if (anchorEl) {
      const positionMenu = () => {
        const menu = document.body.querySelector(
          ".menu.bases-toolbar-views-menu, .bases-toolbar-menu.bases-toolbar-views-menu, .bases-toolbar-menu.view-config-menu"
        );
        if (menu && anchorEl.isConnected) {
          const rect = anchorEl.getBoundingClientRect();
          menu.style.position = "fixed";
          menu.style.top = `${rect.bottom + 4}px`;
          const menuWidth = menu.offsetWidth || 320;
          let left = rect.left;
          if (left + menuWidth > window.innerWidth - 10) {
            left = window.innerWidth - menuWidth - 10;
          }
          menu.style.left = `${Math.max(10, left)}px`;
        }
      };

      setTimeout(positionMenu, 10);
      setTimeout(positionMenu, 40);
      setTimeout(positionMenu, 100);
    }

    // Safely monitor menu lifetime to restore parentEl and hidden state only AFTER it closes
    let menuPollCount = 0;
    const menuPoll = setInterval(() => {
      menuPollCount++;
      const menu = document.body.querySelector(
        ".menu.bases-toolbar-views-menu, .bases-toolbar-menu.bases-toolbar-views-menu, .bases-toolbar-menu.view-config-menu"
      );
      if (!menu && menuPollCount > 2) {
        clearInterval(menuPoll);
        if (wasHidden && this.module.moduleSettings.leftDefaultsMinimized) {
          viewsMenu.classList.add("bases-left-default-hidden");
        }
        if (vm?.toolbarItem?.menu && origParentEl) {
          vm.toolbarItem.menu.parentEl = origParentEl;
        }
      }
      if (menuPollCount > 300) clearInterval(menuPoll);
    }, 200);

    return true;
  }

  applyLeftDefaultsHiddenState(toolbar, isLeftMinimized) {
    const viewsMenu = toolbar.querySelector(".bases-toolbar-views-menu");
    const resultCount = toolbar.querySelector(".bases-toolbar-result-count");
    if (viewsMenu) {
      viewsMenu.classList.toggle("bases-left-default-hidden", isLeftMinimized);
    }
    if (resultCount) {
      resultCount.classList.toggle("bases-left-default-hidden", isLeftMinimized);
    }
  }

  openCommunityBasesVisualsModal() {
    const app = this.module.ctx.app;
    const bpc = app?.plugins?.plugins?.["bases-pill-colors"] || this.module.bpcPlugin;
    if (bpc?.enhancer?.openRuleManager) {
      const scope = this.controller.getCurrentFile?.()?.path || "";
      bpc.enhancer.openRuleManager([], scope);
      return;
    }

    // Fallback: click native bpc toolbar control if present
    const nativeBtn = this.controller.viewHeaderEl?.querySelector(".bpc-conditional-formatting-button .text-icon-button, .bpc-toolbar-control");
    if (nativeBtn) {
      nativeBtn.click();
      return;
    }

    // Fallback notice
    new Notice("Bases Visuals: Open 'Configure view' or enable 'Bases Visuals' in Community Plugins.");
  }

  applyToolsHiddenState(toolbar, isMinimized) {
    toolbar.classList.toggle("is-tools-minimized", isMinimized);
    const candidates = toolbar.querySelectorAll(
      "button, .clickable-icon, [aria-label], .bases-toolbar-item, .bpc-toolbar-control, .bpc-conditional-formatting-button, .bpc-table-layout-button"
    );

    for (const el of Array.from(candidates)) {
      if (
        el.classList.contains("bases-tools-toggle-btn") ||
        el.closest(".bases-tools-toggle-btn") ||
        el.classList.contains("bases-left-defaults-toggle-btn") ||
        el.closest(".bases-left-defaults-toggle-btn") ||
        el.classList.contains("bases-view-config-btn") ||
        el.closest(".bases-view-config-btn") ||
        el.classList.contains("bases-visuals-tab") ||
        el.classList.contains("bases-visuals-tab-strip") ||
        el.closest(".bases-visuals-tab-strip") ||
        el.classList.contains("bases-toolbar-result-count") ||
        el.closest(".bases-toolbar-result-count") ||
        el.classList.contains("bases-toolbar-views-menu") ||
        el.closest(".bases-toolbar-views-menu") ||
        el.classList.contains("bases-toolbar-new-item-menu") ||
        el.closest(".bases-toolbar-new-item-menu")
      ) {
        continue;
      }

      const txt = (el.textContent || "").trim().toLowerCase();
      const label = (el.getAttribute("aria-label") || "").toLowerCase();

      const isCollapsibleTool =
        txt.includes("format") || label.includes("format") ||
        txt.includes("layout") || label.includes("layout") ||
        el.classList.contains("bpc-toolbar-control") ||
        el.closest(".bpc-toolbar-control") ||
        el.classList.contains("bpc-conditional-formatting-button") ||
        el.closest(".bpc-conditional-formatting-button") ||
        el.classList.contains("bpc-table-layout-button") ||
        el.closest(".bpc-table-layout-button") ||
        txt.includes("sort") || label.includes("sort") ||
        txt.includes("filter") || label.includes("filter") ||
        txt.includes("group") || label.includes("group") ||
        txt.includes("propert") || label.includes("propert") ||
        txt.includes("search") || label.includes("search");

      if (isCollapsibleTool) {
        let target = el;
        while (
          target.parentElement &&
          target.parentElement !== toolbar &&
          !target.parentElement.classList.contains("bases-toolbar")
        ) {
          if (
            target.parentElement.querySelector?.(
              ".bases-view-config-btn, .bases-tools-toggle-btn, .bases-left-defaults-toggle-btn, .bases-toolbar-new-item-menu, .bases-visuals-tab-strip"
            )
          ) {
            break;
          }
          if (
            target.parentElement.classList.contains("bases-toolbar-item") ||
            target.parentElement.classList.contains("bpc-toolbar-control") ||
            target.parentElement.classList.contains("bpc-conditional-formatting-button") ||
            target.parentElement.classList.contains("bpc-table-layout-button")
          ) {
            target = target.parentElement;
            break;
          }
          target = target.parentElement;
        }
        if (
          !target.querySelector?.(
            ".bases-view-config-btn, .bases-tools-toggle-btn, .bases-left-defaults-toggle-btn, .bases-toolbar-new-item-menu, .bases-visuals-tab-strip"
          )
        ) {
          target.classList.toggle("bases-tool-hidden", isMinimized);
        }
      }
    }
  }

  // -----------------------------------------------------------------------
  // Pillar 3: Immediate Record Pagination (Hooked into Bases cG.applyLimit)
  // -----------------------------------------------------------------------
  hookBasesDataClass() {
    const DataClass = this.controller.view?.data?.constructor;
    if (DataClass) {
      this.ensureDataClassHooked(DataClass);
    }
  }

  ensureDataClassHooked(DataClass) {
    if (!DataClass || !DataClass.prototype || DataClass.prototype.__basesVisualsHooked) return;
    DataClass.prototype.__basesVisualsHooked = true;

    const origApplyLimit = DataClass.prototype.applyLimit;
    const self = this;

    DataClass.prototype.applyLimit = function (records) {
      const total = records.length;
      const viewConfig = this.config;

      if (!viewConfig) {
        origApplyLimit.call(this, records);
        return;
      }

      const raw = viewConfig.get?.(STORAGE_KEY) || {};
      const paginationEnabled = raw.paginationEnabled !== false;
      const nativeLimit = typeof viewConfig.getLimit === "function" ? viewConfig.getLimit() : 0;

      // Effective page size: explicit setting > native Bases limit > defaultPageSize
      const pageSize =
        typeof raw.pageSize === "number" && raw.pageSize > 0
          ? raw.pageSize
          : nativeLimit > 0
          ? nativeLimit
          : (self.module.moduleSettings.defaultPageSize || DEFAULT_PAGE_SIZE);

      const autoHide = raw.autoHidePagination === true;

      // If pagination is disabled: delegate to native applyLimit
      if (!paginationEnabled) {
        origApplyLimit.call(this, records);
        this.__basesVisualsMeta = {
          totalItems: records.length,
          pageSize,
          currentPage: 1,
          totalPages: 1,
          isPaginated: false
        };
        return;
      }

      const totalPages = Math.max(1, Math.ceil(total / pageSize));
      const currentPage = Math.min(Math.max(1, viewConfig.__currentPage || 1), totalPages);
      viewConfig.__currentPage = currentPage;

      const startIndex = (currentPage - 1) * pageSize;
      const endIndex = Math.min(startIndex + pageSize, total);
      const pageSlice = records.slice(startIndex, endIndex);

      // Mutate records array in-place so Table, Cards, and List views render EXACTLY the slice!
      records.splice(0, records.length, ...pageSlice);

      this.__basesVisualsMeta = {
        totalItems: total,
        pageSize,
        currentPage,
        totalPages,
        startItem: total === 0 ? 0 : startIndex + 1,
        endItem: startIndex + pageSlice.length,
        isPaginated: true
      };
    };
  }

  hookView() {
    const view = this.controller.view;
    if (!view || view.__basesVisualsViewHooked) return;
    view.__basesVisualsViewHooked = true;

    if (typeof view.onDataUpdated === "function") {
      const origOnDataUpdated = view.onDataUpdated.bind(view);
      view.onDataUpdated = () => {
        origOnDataUpdated();
        setTimeout(() => {
          this.updatePaginationBar();
          this.triggerCommunityBasesVisualsEnhancer();
        }, 15);
      };
      this.cleanups.push(() => {
        if (view.__basesVisualsViewHooked) {
          view.onDataUpdated = origOnDataUpdated;
        }
      });
    }
  }

  hookNotifyView() {
    const origNotifyView = this.controller.notifyView?.bind(this.controller);
    if (!origNotifyView || this.controller.__basesVisualsNotifyHooked) return;
    this.controller.__basesVisualsNotifyHooked = true;

    this.controller.notifyView = () => {
      origNotifyView();
      if (this.controller.view?.data?.constructor) {
        this.ensureDataClassHooked(this.controller.view.data.constructor);
      }
      this.hookView();
      setTimeout(() => {
        this.updatePaginationBar();
        this.triggerCommunityBasesVisualsEnhancer();
      }, 15);
    };

    if (typeof this.controller.requestNotifyView === "function" && !this.controller.__basesVisualsReqHooked) {
      this.controller.__basesVisualsReqHooked = true;
      const origReq = this.controller.requestNotifyView.bind(this.controller);
      this.controller.requestNotifyView = () => {
        origReq();
        setTimeout(() => {
          this.updatePaginationBar();
          this.triggerCommunityBasesVisualsEnhancer();
        }, 65);
      };
      this.cleanups.push(() => {
        this.controller.requestNotifyView = origReq;
        delete this.controller.__basesVisualsReqHooked;
      });
    }

    this.cleanups.push(() => {
      if (this.controller.__basesVisualsNotifyHooked) {
        this.controller.notifyView = origNotifyView;
        delete this.controller.__basesVisualsNotifyHooked;
      }
    });
  }

  updatePaginationBar() {
    const settings = this.getSettings();

    if (!settings.paginationEnabled) {
      this.destroyPaginationBar();
      return;
    }

    let meta = this.controller.view?.data?.__basesVisualsMeta;
    const pageSize = settings.pageSize || DEFAULT_PAGE_SIZE;

    // Recalculate or synthesize meta whenever missing or when pageSize changed
    if (!meta || meta.pageSize !== pageSize) {
      const total = Array.isArray(this.controller.view?.data?.data)
        ? this.controller.view.data.data.length
        : (this.controller.results ? this.controller.results.size : 0);
      const totalPages = Math.max(1, Math.ceil(total / pageSize));
      const config = this.getViewConfig();
      const currentPage = Math.min(Math.max(1, config?.__currentPage || 1), totalPages);
      meta = {
        totalItems: total,
        pageSize,
        currentPage,
        totalPages,
        startItem: total === 0 ? 0 : (currentPage - 1) * pageSize + 1,
        endItem: Math.min(currentPage * pageSize, total),
        isPaginated: true
      };
      if (this.controller.view?.data) {
        this.controller.view.data.__basesVisualsMeta = meta;
      }
    }

    if (!this.paginationBarEl) {
      this.paginationBarEl = createDiv({ cls: "bases-pagination-bar" });
    }

    // Attach pagination bar firmly into the DOM
    const view = this.controller.view;
    const container = this.controller.viewContainerEl;
    let targetEl = null;

    if (view) {
      if (view.footerSummary?.el && view.footerSummary.el.parentElement) {
        targetEl = view.footerSummary.el;
      } else if (view.containerEl && view.containerEl.parentElement) {
        targetEl = view.containerEl;
      } else if (view.scrollEl && view.scrollEl.lastElementChild) {
        targetEl = view.scrollEl.lastElementChild;
      }
    }

    if (!targetEl && container) {
      targetEl = container.querySelector(
        ".bases-table-footer, .bases-table-container, .bases-cards-container, .bases-list-container, .bases-table"
      );
    }

    if (targetEl && targetEl.parentElement) {
      if (this.paginationBarEl.previousElementSibling !== targetEl || !this.paginationBarEl.isConnected) {
        targetEl.after(this.paginationBarEl);
      }
    } else if (container) {
      if (this.paginationBarEl.parentElement !== container || !this.paginationBarEl.isConnected) {
        container.appendChild(this.paginationBarEl);
      }
    }

    this.paginationBarEl.empty();

    // 1. Info Label: Showing X–Y of Z results
    const infoEl = this.paginationBarEl.createDiv({ cls: "bases-pagination-info" });
    const countDisplay = meta.totalItems === 0 ? "0" : (meta.startItem + "–" + meta.endItem + " of " + meta.totalItems);
    infoEl.createSpan({ text: "Showing " + countDisplay + " results" });

    // 2. Navigation Controls: [«] [‹] Page X of Y [›] [»]
    const controlsEl = this.paginationBarEl.createDiv({ cls: "bases-pagination-controls" });
    if (settings.autoHidePagination && meta.totalPages <= 1) {
      controlsEl.style.display = "none";
    }

    // First page button
    const firstBtn = controlsEl.createEl("button", {
      cls: "bases-pagination-btn",
      attr: { type: "button", title: "First page" }
    });
    if (setIcon) setIcon(firstBtn, "lucide-chevrons-left"); else firstBtn.setText("«");
    firstBtn.disabled = meta.currentPage <= 1;
    firstBtn.addEventListener("click", () => this.goToPage(1));

    // Previous page button
    const prevBtn = controlsEl.createEl("button", {
      cls: "bases-pagination-btn",
      attr: { type: "button", title: "Previous page" }
    });
    if (setIcon) setIcon(prevBtn, "lucide-chevron-left"); else prevBtn.setText("‹");
    prevBtn.disabled = meta.currentPage <= 1;
    prevBtn.addEventListener("click", () => this.goToPage(meta.currentPage - 1));

    // Page indicator
    controlsEl.createSpan({
      cls: "bases-pagination-pages-label",
      text: "Page " + meta.currentPage + " of " + meta.totalPages
    });

    // Next page button
    const nextBtn = controlsEl.createEl("button", {
      cls: "bases-pagination-btn",
      attr: { type: "button", title: "Next page" }
    });
    if (setIcon) setIcon(nextBtn, "lucide-chevron-right"); else nextBtn.setText("›");
    nextBtn.disabled = meta.currentPage >= meta.totalPages;
    nextBtn.addEventListener("click", () => this.goToPage(meta.currentPage + 1));

    // Last page button
    const lastBtn = controlsEl.createEl("button", {
      cls: "bases-pagination-btn",
      attr: { type: "button", title: "Last page" }
    });
    if (setIcon) setIcon(lastBtn, "lucide-chevrons-right"); else lastBtn.setText("»");
    lastBtn.disabled = meta.currentPage >= meta.totalPages;
    lastBtn.addEventListener("click", () => this.goToPage(meta.totalPages));

    // 3. Page Size Selector
    const sizeWrapper = this.paginationBarEl.createDiv({ cls: "bases-pagination-page-size" });
    sizeWrapper.createSpan({ text: "Page size:" });
    const select = sizeWrapper.createEl("select");
    for (const size of PAGE_SIZES) {
      const opt = select.createEl("option", { text: String(size), value: String(size) });
      if (size === meta.pageSize) opt.selected = true;
    }

    select.addEventListener("change", (e) => {
      const val = parseInt(e.target.value, 10);
      if (val) {
        this.saveSettings({ pageSize: val });
      }
    });

    this.processPillsAndListCells();
  }

  goToPage(pageNumber) {
    const config = this.getViewConfig();
    if (config) {
      config.__currentPage = pageNumber;
      if (typeof this.controller.notifyView === "function") {
        this.controller.notifyView();
      }
    }
  }

  destroyPaginationBar() {
    if (this.paginationBarEl) {
      this.paginationBarEl.remove();
      this.paginationBarEl = null;
    }
  }

  destroy() {
    for (const cleanup of this.cleanups) {
      try { cleanup(); } catch (_) {}
    }
    this.cleanups = [];

    if (this.tabStripEl) {
      this.tabStripEl.remove();
      this.tabStripEl = null;
    }
    if (this.toolsToggleBtn) {
      this.toolsToggleBtn.remove();
      this.toolsToggleBtn = null;
    }
    if (this.visualsBtn) {
      this.visualsBtn.remove();
      this.visualsBtn = null;
    }
    this.destroyPaginationBar();

    const toolbar = this.controller.viewHeaderEl?.querySelector(".bases-toolbar");
    toolbar?.removeClass("has-bases-visuals-tabs");
    toolbar?.removeClass("is-tools-minimized");
  }
}

// -------------------------------------------------------------------------
// Configure View Modal/Menu Observer (Clean, Zero Horizontal Scroll)
// -------------------------------------------------------------------------
class BasesViewConfigObserver {
  constructor(moduleInstance) {
    this.module = moduleInstance;
    this.observer = new MutationObserver((mutations) => {
      let shouldScan = false;
      for (const m of mutations) {
        for (const n of m.addedNodes) {
          if (n.nodeType === 1) {
            if (
              n.matches?.(".view-config-menu, .bases-toolbar-menu-form") ||
              n.querySelector?.(".view-config-menu, .bases-toolbar-menu-form")
            ) {
              shouldScan = true;
              break;
            }
          }
        }
        if (shouldScan) break;
      }
      if (shouldScan) {
        if (!this._rafScan) {
          this._rafScan = requestAnimationFrame(() => {
            this._rafScan = null;
            this.scanForMenus();
          });
        }
      }
    });
    this.observer.observe(document.body, { childList: true, subtree: true });
    this.scanForMenus();
  }

  scanForMenus() {
    const menus = document.body.querySelectorAll(".bases-toolbar-menu-form.view-config-menu");
    for (const menu of Array.from(menus)) {
      if (menu.querySelector(".bases-visuals-config-container")) continue;
      this.injectConfigSection(menu);
    }
  }

  injectConfigSection(menuForm) {
    // Determine configured view name from form input if available
    const nameInput = menuForm.querySelector('.input-row input[type="text"], .input-row input');
    const configuredViewName = nameInput ? nameInput.value.trim() : null;

    // Determine active controller and host
    const activeHost = (configuredViewName ? this.module.getHostForViewName(configuredViewName) : null) || this.module.getActiveHost();
    if (!activeHost) return;

    const viewDef = (configuredViewName && activeHost.controller?.query?.getViewConfig)
      ? (activeHost.controller.query.getViewConfig(configuredViewName) || activeHost.getViewConfig())
      : activeHost.getViewConfig();
    if (!viewDef) return;

    const settings = activeHost.getSettings(viewDef);

    const container = menuForm.createDiv("bases-visuals-config-container");
    container.createDiv("input-group-divider");

    // 1. Tab Settings Section
    const tabGroup = container.createDiv("input-group-container");
    tabGroup.createDiv({ cls: "input-group-header", text: "View Tabs Settings" });
    const tabContent = tabGroup.createDiv("input-group-content");

    // Show in tabs toggle
    const showRow = this.createRow(tabContent, "Show in tabs", "mod-toggle");
    new ToggleComponent(showRow.querySelector(".input-row-content"))
      .setValue(settings.showTabs)
      .onChange(val => activeHost.saveSettings({ showTabs: val }, viewDef));

    // Tab Color dropdown
    const colorRow = this.createRow(tabContent, "Tab color");
    const colorSelect = new DropdownComponent(colorRow.querySelector(".input-row-content"))
      .addOption("", "Default");
    for (const c of TAB_COLORS) {
      colorSelect.addOption(c, c.charAt(0).toUpperCase() + c.slice(1));
    }
    colorSelect.setValue(settings.tabColor || "").onChange(val => activeHost.saveSettings({ tabColor: val || null }, viewDef));

    // Tab Size dropdown
    const sizeRow = this.createRow(tabContent, "Tab size");
    const sizeSelect = new DropdownComponent(sizeRow.querySelector(".input-row-content"));
    for (const s of TAB_SIZES) {
      sizeSelect.addOption(s, s.charAt(0).toUpperCase() + s.slice(1));
    }
    sizeSelect.setValue(settings.tabSize || "medium").onChange(val => activeHost.saveSettings({ tabSize: val }, viewDef));

    // Tab Icon Row using Iconic library picker
    const iconRow = this.createRow(tabContent, "Tab icon");
    const iconContent = iconRow.querySelector(".input-row-content");
    iconContent.empty();

    const currentIcon = settings.tabIcon ||
      activeHost.controller?.plugin?.getRegistration?.(viewDef?.type)?.icon ||
      activeHost.controller?.plugin?.viewTypes?.get?.(viewDef?.type)?.icon ||
      viewDef?.icon ||
      activeHost.getDefaultViewIcon(viewDef?.type);

    const iconPickerBtn = iconContent.createEl("button", {
      cls: "bases-visuals-iconic-picker-btn button",
      attr: { type: "button", title: "Choose icon from Iconic library" }
    });

    const iconPreview = iconPickerBtn.createSpan({ cls: "bases-visuals-tab-icon-preview" });
    if (setIcon && currentIcon) {
      try { setIcon(iconPreview, currentIcon); } catch (_) {}
    }

    const iconLabel = iconPickerBtn.createSpan({
      cls: "bases-visuals-tab-icon-label",
      text: settings.tabIcon ? settings.tabIcon.replace(/^lucide-/, "") : "Default (View Icon)"
    });

    iconPickerBtn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      activeHost.openIconicPickerForView(viewDef, (newIcon, newColor) => {
        const patch = { tabIcon: newIcon || null };
        if (newColor) patch.tabColor = newColor;
        activeHost.saveSettings(patch, viewDef);

        iconLabel.textContent = newIcon ? newIcon.replace(/^lucide-/, "") : "Default (View Icon)";
        iconPreview.empty();
        const displayIco = newIcon || currentIcon;
        if (setIcon && displayIco) {
          try { setIcon(iconPreview, displayIco); } catch (_) {}
        }
      });
    });

    if (settings.tabIcon) {
      const resetBtn = iconContent.createEl("button", {
        cls: "clickable-icon bases-visuals-icon-reset-btn",
        attr: { type: "button", title: "Reset to default view icon", "aria-label": "Reset icon" }
      });
      if (setIcon) setIcon(resetBtn, "lucide-rotate-ccw"); else resetBtn.setText("↺");
      resetBtn.addEventListener("click", (e) => {
        e.preventDefault();
        e.stopPropagation();
        activeHost.saveSettings({ tabIcon: null }, viewDef);
        iconLabel.textContent = "Default (View Icon)";
        iconPreview.empty();
        if (setIcon && currentIcon) {
          try { setIcon(iconPreview, currentIcon); } catch (_) {}
        }
        resetBtn.remove();
      });
    }

    // Divider between sections
    container.createDiv("input-group-divider");

    // 2. Pagination Settings Section
    const pageGroup = container.createDiv("input-group-container");
    pageGroup.createDiv({ cls: "input-group-header", text: "Pagination Settings" });
    const pageContent = pageGroup.createDiv("input-group-content");

    // Enable pagination toggle
    const enablePageRow = this.createRow(pageContent, "Enable pagination", "mod-toggle");
    new ToggleComponent(enablePageRow.querySelector(".input-row-content"))
      .setValue(settings.paginationEnabled)
      .onChange(val => activeHost.saveSettings({ paginationEnabled: val }, viewDef));

    // Page size dropdown
    const pageSizeRow = this.createRow(pageContent, "Page size");
    const pageSizeSelect = new DropdownComponent(pageSizeRow.querySelector(".input-row-content"));
    for (const size of PAGE_SIZES) {
      pageSizeSelect.addOption(String(size), String(size));
    }
    pageSizeSelect.setValue(String(settings.pageSize || DEFAULT_PAGE_SIZE))
      .onChange(val => activeHost.saveSettings({ pageSize: parseInt(val, 10) }, viewDef));

    // Auto-hide when items <= Page size toggle
    const autoHideRow = this.createRow(pageContent, "Auto-hide single page", "mod-toggle");
    new ToggleComponent(autoHideRow.querySelector(".input-row-content"))
      .setValue(settings.autoHidePagination)
      .onChange(val => activeHost.saveSettings({ autoHidePagination: val }, viewDef));
  }

  createRow(parent, labelText, extraCls = "") {
    const row = parent.createDiv(`input-row ${extraCls}`.trim());
    row.createDiv({ cls: "input-row-label", text: labelText });
    row.createDiv("input-row-content");
    return row;
  }

  destroy() {
    this.observer.disconnect();
    document.body.querySelectorAll(".bases-visuals-config-container").forEach(el => el.remove());
  }
}
// -------------------------------------------------------------------------
// Standalone Settings Tab for Sync Engine
// -------------------------------------------------------------------------
class BasesVisualsSettingTab extends (PluginSettingTab || class {}) {
  constructor(app, hostPlugin, moduleInstance) {
    const myId = moduleInstance ? moduleInstance.getModuleId() : "bases-visuals";
    const pluginProxy = {
      app: app,
      manifest: {
        id: myId,
        name: moduleInstance ? moduleInstance.getModuleName() : "Bases Visuals & Pagination",
        version: "1.2.0"
      }
    };
    super(app, pluginProxy);
    this.module = moduleInstance;
  }

  display() {
    const { containerEl } = this;
    containerEl.empty();

    containerEl.createEl("h2", { text: `${this.module.getModuleName()} Settings` });
    containerEl.createEl("p", {
      text: "Universal View Tabs, toolbar tools minimization toggle, Bases Visuals integration, and record pagination for Obsidian Bases across standalone leaves and transcluded notes."
    });

    const settings = this.module.moduleSettings;

    // Setting: Global Default Page Size
    const pageSizeRow = containerEl.createDiv("setting-item");
    const info = pageSizeRow.createDiv("setting-item-info");
    info.createDiv({ cls: "setting-item-name", text: "Global Default Page Size" });
    info.createDiv({ cls: "setting-item-description", text: "Default number of records per page when a view does not specify a custom page size." });
    const ctrl = pageSizeRow.createDiv("setting-item-control");
    const select = ctrl.createEl("select");
    for (const size of PAGE_SIZES) {
      const opt = select.createEl("option", { text: String(size), value: String(size) });
      if (size === settings.defaultPageSize) opt.selected = true;
    }
    select.addEventListener("change", (e) => {
      settings.defaultPageSize = parseInt(e.target.value, 10);
      this.module.saveSettings();
    });

    // Setting: Auto-hide pagination bar when total items fit on 1 page
    const autoHideRow = containerEl.createDiv("setting-item");
    const info2 = autoHideRow.createDiv("setting-item-info");
    info2.createDiv({ cls: "setting-item-name", text: "Auto-hide Single Page Pagination" });
    info2.createDiv({ cls: "setting-item-description", text: "Automatically hide the pagination footer bar when all results fit on a single page." });
    const ctrl2 = autoHideRow.createDiv("setting-item-control");
    new ToggleComponent(ctrl2)
      .setValue(settings.autoHidePagination)
      .onChange((val) => {
        settings.autoHidePagination = val;
        this.module.saveSettings();
      });

    // Setting: Enable on Transcluded Bases
    const embedRow = containerEl.createDiv("setting-item");
    const info3 = embedRow.createDiv("setting-item-info");
    info3.createDiv({ cls: "setting-item-name", text: "Enable on Transcluded Bases" });
    info3.createDiv({ cls: "setting-item-description", text: "Enable view tabs, tools toggle, and pagination inside embedded bases (![[file.base]]) in Markdown notes." });
    const ctrl3 = embedRow.createDiv("setting-item-control");
    new ToggleComponent(ctrl3)
      .setValue(settings.enableOnEmbeds)
      .onChange((val) => {
        settings.enableOnEmbeds = val;
        this.module.saveSettings();
      });

    // Setting: Remember Collapsed Tools State
    const toolsRow = containerEl.createDiv("setting-item");
    const info4 = toolsRow.createDiv("setting-item-info");
    info4.createDiv({ cls: "setting-item-name", text: "Minimize Right Tools by Default" });
    info4.createDiv({ cls: "setting-item-description", text: "Keep right-side toolbar tools (Sort, Filter, Group, Properties) collapsed by default." });
    const ctrl4 = toolsRow.createDiv("setting-item-control");
    new ToggleComponent(ctrl4)
      .setValue(settings.toolsMinimized)
      .onChange((val) => {
        settings.toolsMinimized = val;
        this.module.saveSettings();
        this.module.syncAllToolsVisibility();
      });

    // Setting: Remember Collapsed Left Defaults State
    const leftDefaultsRow = containerEl.createDiv("setting-item");
    const info5 = leftDefaultsRow.createDiv("setting-item-info");
    info5.createDiv({ cls: "setting-item-name", text: "Minimize Default View Header by Default" });
    info5.createDiv({ cls: "setting-item-description", text: "Collapse default view title and result count on the left toolbar to prioritize view tabs." });
    const ctrl5 = leftDefaultsRow.createDiv("setting-item-control");
    new ToggleComponent(ctrl5)
      .setValue(settings.leftDefaultsMinimized)
      .onChange((val) => {
        settings.leftDefaultsMinimized = val;
        this.module.saveSettings();
        this.module.syncAllLeftDefaultsVisibility();
      });
  }
}

// -------------------------------------------------------------------------
// Main Sync Engine Module Class
// -------------------------------------------------------------------------
class BasesVisualsModule {
  constructor(ctx) {
    this.ctx = ctx;
    this.cleanups = [];
    this.hosts = new Map(); // Map<Controller, BasesVisualsHost>
    this.configObserver = null;
    this.settingTab = null;

    this.moduleSettings = {
      defaultPageSize: DEFAULT_PAGE_SIZE,
      autoHidePagination: true,
      enableOnEmbeds: true,
      toolsMinimized: false,
      leftDefaultsMinimized: false
    };

    this.ensureDiscovered();
  }

  getModuleId() {
    if (this.ctx.loadedModules) {
      for (const [id, modClass] of this.ctx.loadedModules.entries()) {
        if (modClass === this.constructor) return id;
      }
    }
    return "bases-visuals";
  }

  getModuleName() {
    const myId = this.getModuleId();
    const meta = this.ctx.discoveredModules?.get(myId);
    if (meta && meta.name) return meta.name;
    return "Bases Visuals & Pagination";
  }

  ensureDiscovered() {
    const myId = this.getModuleId();
    const existing = this.ctx.discoveredModules?.get(myId);
    const meta = {
      id: myId,
      name: existing?.name || "Bases Visuals & Pagination",
      version: existing?.version || "1.2.0",
      description: existing?.description || "Universal View Tabs, right-tools collapse toggle, Bases Visuals integration, and record pagination for Obsidian Bases across standalone leaves and transcluded notes.",
      icon: existing?.icon || "layout-grid",
      enabled: existing?.enabled !== undefined ? existing.enabled : true
    };

    if (this.ctx.discoveredModules) {
      this.ctx.discoveredModules.set(myId, meta);
    }

    if (this.ctx.indexedDB) {
      try {
        const vaultName = this.ctx.app?.vault?.getName() || "";
        const storeName = `modules-${getVaultHash(vaultName)}`;
        const store = this.ctx.indexedDB.getStore(storeName);
        if (store && store.set) {
          store.set(myId, meta).catch(() => {});
        }
      } catch (_) {}
    }
  }

  getHostForViewName(viewName) {
    if (!viewName) return null;
    for (const host of this.hosts.values()) {
      if (host.controller.viewName === viewName) return host;
      const allNames = host.controller.getQueryViewNames?.() || [];
      if (allNames.includes(viewName)) return host;
    }
    return null;
  }

  getActiveHost() {
    const app = this.ctx.app;
    if (!app?.workspace) return null;

    const activeLeaf = app.workspace.activeLeaf;
    if (activeLeaf?.view?.getViewType?.() === "bases" && activeLeaf.view.controller) {
      return this.hosts.get(activeLeaf.view.controller) || null;
    }

    for (const [controller, host] of this.hosts.entries()) {
      if (controller.viewHeaderEl?.querySelector(".bases-toolbar-views-menu .has-active-menu")) {
        return host;
      }
    }

    for (const host of this.hosts.values()) {
      return host;
    }
    return null;
  }

  syncAllToolsVisibility() {
    const isMin = !!this.moduleSettings.toolsMinimized;
    for (const host of this.hosts.values()) {
      const toolbar = host.controller.viewHeaderEl?.querySelector(".bases-toolbar");
      if (toolbar) {
        host.applyToolsHiddenState(toolbar, isMin);
        if (host.toolsToggleBtn) {
          if (setIcon) {
            setIcon(host.toolsToggleBtn, isMin ? "chevrons-left" : "chevrons-right");
          } else {
            host.toolsToggleBtn.setText(isMin ? "«" : "»");
          }
          host.toolsToggleBtn.setAttribute("aria-label", isMin ? "Expand right tools" : "Minimize right tools");
        }
      }
    }
  }

  syncAllLeftDefaultsVisibility() {
    const isLeftMin = !!this.moduleSettings.leftDefaultsMinimized;
    for (const host of this.hosts.values()) {
      const toolbar = host.controller.viewHeaderEl?.querySelector(".bases-toolbar");
      if (toolbar) {
        host.applyLeftDefaultsHiddenState(toolbar, isLeftMin);
        const leftBtn = toolbar.querySelector(".bases-left-defaults-toggle-btn");
        if (leftBtn) {
          if (setIcon) {
            setIcon(leftBtn, isLeftMin ? "chevrons-right" : "chevrons-left");
          } else {
            leftBtn.setText(isLeftMin ? "»" : "«");
          }
          leftBtn.setAttribute(
            "aria-label",
            isLeftMin ? "Expand default view header" : "Minimize default view header"
          );
          leftBtn.title = isLeftMin ? "Expand default view header" : "Minimize default view header";
        }
      }
    }
  }

  start = async () => {
    const { app, registerCss } = this.ctx;
    this.ensureDiscovered();
    await this.loadSettings();


    // 1. Ensure community plugin "bases-pill-colors" (Bases Visuals) is enabled or start embedded engine
    let bpcCommunity = app?.plugins?.plugins?.["bases-pill-colors"];
    if (app?.plugins && !bpcCommunity) {
      try {
        if (app.plugins.manifests?.["bases-pill-colors"]) {
          await app.plugins.enablePlugin("bases-pill-colors");
          bpcCommunity = app.plugins.plugins?.["bases-pill-colors"];
        }
      } catch (_) {}
    }

    if (!bpcCommunity) {
      try {
        const BPCClass = getBasesPillColorsClass(obsidianApi);
        this.bpcPlugin = new BPCClass(app, {
          id: "bases-pill-colors",
          name: "Bases Visuals",
          version: "0.20.0"
        });
        this.bpcPlugin.loadData = async () => {
          try {
            const f = ".obsidian/plugins/bases-pill-colors/data.json";
            if (await app.vault.adapter.exists(f)) {
              return JSON.parse(await app.vault.adapter.read(f));
            }
          } catch (_) {}
          return this.moduleSettings.bpcData || {};
        };
        this.bpcPlugin.saveData = async (data) => {
          this.moduleSettings.bpcData = data;
          this.saveSettings();
          try {
            const dir = ".obsidian/plugins/bases-pill-colors";
            if (!(await app.vault.adapter.exists(dir))) await app.vault.adapter.mkdir(dir);
            await app.vault.adapter.write(dir + "/data.json", JSON.stringify(data, null, 2));
          } catch (_) {}
        };
        await this.bpcPlugin.onload();
        this.cleanups.push(() => {
          try { this.bpcPlugin?.onunload(); } catch (_) {}
          this.bpcPlugin = null;
        });
      } catch (err) {
        console.warn("[BasesVisuals] Embedded BPC engine notice:", err);
      }
    }


    // 2. Inject Module CSS
    if (registerCss) {
      this.cleanups.push(registerCss(MODULE_CSS));
    } else {
      const styleEl = document.createElement("style");
      styleEl.id = "bases-visuals-styles";
      styleEl.textContent = MODULE_CSS;
      document.head.appendChild(styleEl);
      this.cleanups.push(() => styleEl.remove());
    }

    // 3. Register Standalone Setting Tab
    if (app?.setting && PluginSettingTab) {
      try {
        this.settingTab = new BasesVisualsSettingTab(app, null, this);
        app.setting.pluginTabs.push(this.settingTab);
        this.cleanups.push(() => {
          if (this.settingTab) {
            const idx = app.setting.pluginTabs.indexOf(this.settingTab);
            if (idx !== -1) app.setting.pluginTabs.splice(idx, 1);
            this.settingTab = null;
          }
        });
      } catch (_) {}
    }

    // 4. Hook Embed Registry for Transcluded Bases
    this.hookEmbedRegistry();

    // 5. Hook Workspace Events (Debounced via requestAnimationFrame)
    if (app?.workspace) {
      const syncReq = () => this.requestSyncControllers();
      app.workspace.onLayoutReady(() => syncReq());

      const e1 = app.workspace.on("active-leaf-change", () => syncReq());
      const e2 = app.workspace.on("layout-change", () => syncReq());
      this.cleanups.push(() => {
        app.workspace.offref?.(e1);
        app.workspace.offref?.(e2);
      });

      syncReq();
    }

    // 6. Initialize Configure View Form Observer
    this.configObserver = new BasesViewConfigObserver(this);
    this.cleanups.push(() => this.configObserver?.destroy());

    // 7. Tab Panels & Embeds DOM Watcher
    const handleTabPanelInteraction = (e) => {
      const tabEl = e.target?.closest?.(".tab-panel-container .tab, [class*='tab-panel'] .tab");
      if (tabEl) {
        setTimeout(() => {
          this.syncAllControllers();
          for (const host of this.hosts.values()) {
            if (host.controller?.viewContainerEl?.isConnected) {
              host.renderTabs();
              host.syncToolbarTools();
              host.updatePaginationBar();
              host.triggerCommunityBasesVisualsEnhancer();
            }
          }
        }, 60);
      }
    };
    document.addEventListener("click", handleTabPanelInteraction, true);
    this.cleanups.push(() => document.removeEventListener("click", handleTabPanelInteraction, true));

    const tabMutationObserver = new MutationObserver((mutations) => {
      // Never disturb toolbar tabs while a menu or Configure view popover is open, but preserve pagination bar
      if (document.body.querySelector(".menu, .bases-toolbar-menu-form.view-config-menu")) {
        for (const host of this.hosts.values()) {
          if (host.getSettings().paginationEnabled && !host.paginationBarEl?.isConnected) {
            host.updatePaginationBar();
          }
        }
        return;
      }

      let needsRefresh = false;
      for (const m of mutations) {
        if (m.type === "attributes" && m.attributeName === "class") {
          const t = m.target;
          if (t?.closest?.(".menu, .bases-toolbar-menu, .modal, .bases-toolbar, .bases-visuals-config-container")) {
            continue;
          }
          if (t?.classList?.contains?.("selected") || t?.closest?.(".tab-panel-container")) {
            needsRefresh = true;
            break;
          }
        } else if (m.type === "childList") {
          for (const node of Array.from(m.addedNodes)) {
            if (node.nodeType === 1) {
              if (node.closest?.(".menu, .bases-toolbar-menu, .bases-visuals-config-container")) {
                continue;
              }
              if (node.matches?.(".bases-embed, .bases-view, .tab-panel-container") || node.querySelector?.(".bases-embed, .bases-view, .tab-panel-container")) {
                needsRefresh = true;
                break;
              }
            }
          }
        }
      }
      if (needsRefresh) {
        if (this._tabRefreshTimer) clearTimeout(this._tabRefreshTimer);
        this._tabRefreshTimer = setTimeout(() => {
          this._tabRefreshTimer = null;
          if (document.body.querySelector(".menu, .bases-toolbar-menu-form.view-config-menu")) {
            return;
          }
          this.requestSyncControllers();
        }, 80);
      }
    });

    try {
      tabMutationObserver.observe(document.body, {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: ["class"]
      });
      this.cleanups.push(() => tabMutationObserver.disconnect());
    } catch (_) {}

    console.log(`[BasesVisuals] Module v1.2.1 started successfully.`);
  };

  hookEmbedRegistry() {
    const app = this.ctx.app;
    if (!app?.embedRegistry?.embedByExtension) return;

    const originalBaseEmbedCreator = app.embedRegistry.embedByExtension["base"];
    if (typeof originalBaseEmbedCreator !== "function") return;

    const self = this;
    app.embedRegistry.embedByExtension["base"] = function (ctx, file, subpath) {
      const embedInstance = originalBaseEmbedCreator.apply(this, arguments);
      if (embedInstance && self.moduleSettings.enableOnEmbeds) {
        const origLoadFile = embedInstance.loadFile?.bind(embedInstance);
        if (origLoadFile) {
          embedInstance.loadFile = async function () {
            const res = await origLoadFile();
            const tryAttach = () => {
              if (embedInstance.controller && self.isValidController(embedInstance.controller)) {
                self.attachHost(embedInstance.controller);
                embedInstance.register?.(() => self.detachHost(embedInstance.controller));
                return true;
              }
              return false;
            };
            if (!tryAttach()) {
              setTimeout(tryAttach, 50);
              setTimeout(tryAttach, 250);
              setTimeout(tryAttach, 600);
            }
            return res;
          };
        }
      }
      return embedInstance;
    };

    this.cleanups.push(() => {
      app.embedRegistry.embedByExtension["base"] = originalBaseEmbedCreator;
    });
  }

  requestSyncControllers() {
    if (this._syncRaf) return;
    this._syncRaf = requestAnimationFrame(() => {
      this._syncRaf = null;
      this.syncAllControllers();
    });
  }

  syncAllControllers() {
    const app = this.ctx.app;
    if (!app?.workspace) return;

    const activeControllers = new Set();

    // 1. Scan Standalone Leaves
    const baseLeaves = app.workspace.getLeavesOfType?.("bases") || [];
    for (const leaf of baseLeaves) {
      const controller = leaf.view?.controller;
      if (this.isValidController(controller)) {
        activeControllers.add(controller);
        this.attachHost(controller);
      }
    }

    // 2. Scan Markdown Leaves for Transcluded Bases
    if (this.moduleSettings.enableOnEmbeds) {
      const mdLeaves = app.workspace.getLeavesOfType?.("markdown") || [];
      for (const leaf of mdLeaves) {
        this.findControllersInComponentTree(leaf.view, (ctrl) => {
          if (this.isValidController(ctrl)) {
            activeControllers.add(ctrl);
            this.attachHost(ctrl);
          }
        });
      }

      // 3. Scan Plugin Component Trees (only when tab panels or embeds are present in the DOM)
      const hasEmbedOrPanel = !!document.body.querySelector(".tab-panel-container, .bases-embed");
      if (hasEmbedOrPanel && app.plugins?.plugins) {
        for (const plugin of Object.values(app.plugins.plugins)) {
          if (plugin && Array.isArray(plugin._children)) {
            this.findControllersInComponentTree(plugin, (ctrl) => {
              if (this.isValidController(ctrl)) {
                activeControllers.add(ctrl);
                this.attachHost(ctrl);
              }
            });
          }
        }
      }
    }

    // Clean up hosts for closed leaves
    for (const [ctrl, host] of this.hosts.entries()) {
      if (!activeControllers.has(ctrl) && !ctrl.viewContainerEl?.isConnected) {
        this.detachHost(ctrl);
      }
    }
  }

  findControllersInComponentTree(component, callback, depth = 0, visited = new Set()) {
    if (!component || depth > 25 || visited.has(component)) return;
    visited.add(component);
    if (component.controller && this.isValidController(component.controller)) {
      callback(component.controller);
    }
    if (Array.isArray(component._children)) {
      for (const child of component._children) {
        this.findControllersInComponentTree(child, callback, depth + 1, visited);
      }
    }
  }

  isValidController(ctrl) {
    return (
      ctrl &&
      typeof ctrl.getQueryViewNames === "function" &&
      typeof ctrl.selectView === "function" &&
      ctrl.viewHeaderEl instanceof HTMLElement
    );
  }

  attachHost(controller) {
    if (!this.hosts.has(controller)) {
      const host = new BasesVisualsHost(controller, this);
      this.hosts.set(controller, host);
    } else {
      const host = this.hosts.get(controller);
      if (host.controller?.viewHeaderEl?.isConnected) {
        if (!host.tabStripEl?.isConnected || !host.paginationBarEl?.isConnected || host.needsRender) {
          host.renderTabs();
          host.syncToolbarTools();
          host.updatePaginationBar();
          host.processPillsAndListCells();
          host.needsRender = false;
        }
      }
    }
  }

  detachHost(controller) {
    const host = this.hosts.get(controller);
    if (host) {
      host.destroy();
      this.hosts.delete(controller);
    }
  }

  dispose = () => {
    for (const host of this.hosts.values()) {
      try { host.destroy(); } catch (_) {}
    }
    this.hosts.clear();

    for (const cleanup of this.cleanups) {
      try { cleanup(); } catch (_) {}
    }
    this.cleanups = [];

    console.log(`[BasesVisuals] Module disposed.`);
  };

  async loadSettings() {
    const myId = this.getModuleId();
    const stored = this.ctx.settings?.modules?.[myId]?.basesVisualsSettings;
    if (stored) {
      this.moduleSettings = Object.assign(this.moduleSettings, stored);
    }
  }

  async saveSettings() {
    const myId = this.getModuleId();
    if (!this.ctx.settings.modules) this.ctx.settings.modules = {};
    if (!this.ctx.settings.modules[myId]) {
      this.ctx.settings.modules[myId] = { enabled: true };
    }
    this.ctx.settings.modules[myId].basesVisualsSettings = this.moduleSettings;

    if (this.ctx.saveSettings) {
      await this.ctx.saveSettings();
    }

    for (const host of this.hosts.values()) {
      host.renderTabs();
      host.syncToolbarTools();
      host.updatePaginationBar();
    }
  }
}

export { BasesVisualsModule as default };
